  // Lore tablets.
  const TABLETS = {
    "Abyss_06_Core": [["Ancient_Basin","ABYSS_TUT_TAB_01",60.76,232.62,{"es":"Seres superiores, estas palabras son solo para vosotros.\n \nNuestro Receptáculo puro ha ascendido.\nTras de sí deja tan solo el arrepentimiento y el rechazo producido por su creación.\nNo volveremos a entrar en ese lugar nunca más.","en":"Higher beings, these words are for you alone.\n\nOur pure Vessel has ascended.\nBeyond lies only the refuse and regret of its creation.\nWe shall enter that place no longer."}]],
    "Cliffs_01": [["Howling_Cliffs","CLIFF_TAB_02",127.3,57.72,{"es":"Seres superiores, estas palabras son solo para vosotros.\n \nEstas llanuras malditas se extienden hasta el infinito. No hay nada más allá.\nLos necios que quieran atravesar este vacío deberán pagar el precio y renunciar a las valiosas mentes que este reino otorga.","en":"Higher beings, these words are for you alone.\n\nThese blasted plains stretch never-ending. There is no world beyond.\nThose foolish enough to traverse this void must pay the toll and relinquish the precious mind this kingdom grants."}]],
    "Crossroads_11_alt": [["Pilgrim's_Way_1","PILGRIM_TAB_01",105.95,14.66,{"es":"El Camino del Peregrino\nViajeros de Hallownest, descended por las verdes espesuras y las arboledas fúngicas hasta la ciudad, en el corazón del Reino.\nAllí todos los deseos se cumplirán, y las preguntas hallarán respuesta.","en":"The Pilgrim's Way\nTravellers of Hallownest, descend through verdant wilds and fungal groves to the city at this kingdom's heart.\nThere all wishes shall be granted, all truths revealed."}]],
    "Deepnest_East_17": [["Kingdom's_Edge","MR_MUSH_RIDDLE_TAB_NORMAL",32.55,210.53,{"es":"Escucha el camino del Heraldo Maestro, que señalará el fin de una Edad.\n \n\nNacen de sí mismos, su mente es una.\nCerca de donde surge la ácida laguna.\n \n\nBrillando en abismos oscuros y serpenteantes.\nDonde aúllan los vientos, sobre fósiles tambaleantes. \n \n\nAquí los monarcas vuelan en aires indolentes.\nEn la tierra de Raíz, donde el caracol yace inerte.\n \n\nAl Sendero del Wyrm, que nuevas tierras deja ver.\nAhí termina su viaje, tras el Reino recorrer.","en":"We speak the path of the Master Herald, he who would signal an Age's end.\n \n\nSpawn of self, their minds unite,\nAside the source of acid blight,\n \n\nAglow in darkest, winding depths,\nWinds all howl above fossilstone steps,\n \n\nMonarchflys in airs set still,\nTo Root's domain and snail once shrill,\n \n\nPath of Wyrm, at new lands entered,\nThere journeys end. The kingdom ventured."}]],
    "Fungus1_13": [["Greenpath_QG","GREEN_TABLET_07",54.52,10.63,{"es":"Aunque estas tierras antaño fueron nuestras, un ser pálido reclama las cavernas que se extienden más adelante.\nParece benevolente, pero no comparte nuestro sueño.\nSi te aventuras en ese lugar, ten cuidado.","en":"Though once our lands, a pale being lays claim to the caverns ahead.\nIt may appear benevolent but it does not share our dream.\nBe wary to wander that place."}]],
    "Fungus1_17": [["Greenpath_Upper_Hidden","GREEN_TABLET_06",67.3,26.32,{"es":"Unn, el Oculto, te necesitamos ahora.\nNos hemos cansado de estar lejos de ti.\nNuestras hojas caen.","en":"Hidden Unn, we need you now.\nWe grow tired away from you.\nOur leaves are falling."}]],
    "Fungus1_19": [["Greenpath_Lower_Hidden","GREEN_TABLET_02",86.57,3.82,{"es":"Aquellos que abandonen las sendas del Rey Blanco se enfrentarán a la ley de Unn.","en":"Those who stray from the White King's roads shall face the law of Unn."}]],
    "Fungus1_21": [["Greenpath_Stag","GREEN_TABLET_05",78.1,36.72,{"es":"Los Niños Verdes abandonaron el mundo del sueño y entraron en estas tierras.\nAhora esperamos, pacientes, la llamada para regresar.","en":"The Green Children walked from the dream unto these lands.\nHere we now shall wait, patient, for the call to return."}]],
    "Fungus1_30": [["Greenpath_Below_Toll","GREEN_TABLET_01",42.12,3.59,{"es":"Nuestra vida procede del musgo y las hojas.\nMientras crezcan en el sendero, perduraremos.","en":"From moss and leaf our life is drawn.\nWhile it grows upon the path we shall never wilt."}]],
    "Fungus1_32": [["Greenpath_Lifeblood","GREEN_TABLET_03",9.69,34.78,{"es":"La gran mente soñó en una ocasión con hojas, y estas cavernas se llenaron de ellas.\nLa mente de Unn puede percibirse en cada arbusto y cada brote.","en":"The greater mind once dreamed of leaf and cast these caverns so.\nIn every bush and every vine the mind of Unn reveals itself to us."}]],
    "Fungus2_04": [["Fungal_Wastes_Below_Shrumal_Ogres","FUNG_TAB_01",32.44,11.72,{"es":"Aceptaremos la voluntad del Wyrm con cautela.\nSus premoniciones nos protegen.\nEnlazaremos el futuro y el destino.","en":"Warily shall we accept the will of the Wyrm.\nIts prescience shields us.\nFate and Future we shall entwine."}]],
    "Fungus2_07": [["Fungal_Wastes_Hidden","FUNG_TAB_03",19.87,30.19,{"es":"Nuestra comunión nos hace fuertes.\nNuestra unión mental nos fortalece.\nEn cada insecto que pasa por nuestros caminos\n solo percibimos la melancolía de la individualidad.","en":"Strength in the shared self.\nStrength in the mind united.\nIn every bug that would pass upon our roads,\nonly the melancholy of disparity."}]],
    "Fungus2_12": [["Mantis_Outskirts","MANTIS_PLAQUE_01",158.59,11.71,{"es":"Viajeros que buscáis la muerte, sed bienvenidos\nQue nuestras garras os otorguen un final rápido e indoloro.","en":"Wanderers seeking death, welcome.\nMay you find swift end upon our claws."}]],
    "Fungus2_14": [["Mantis_Village","MANTIS_PLAQUE_02",47.23,26.94,{"es":"La tregua continúa. Permanecemos vigilantes. Las bestias no se acercarán.","en":"The truce remains.\nOur vigil holds.\nThe beasts are kept at bay."}]],
    "Fungus2_20": [["Spore_Shroom","FUNG_TAB_04",56.85,41.54,{"es":"Esta frontera mantiene a raya lo que rasga y se retuerce.\nSu señor muerto, de una casta antaño honrada.\nSu madre sellada, ahora tan solo una bestia común.\nNo hay paz entre ellos y nuestro pueblo.","en":"This border bounds the twisting, scratching things.\nTheir dead sire, once of honoured caste. \nTheir sealed mother, but the common beast.\nNo peace with them we make."}]],
    "Fungus2_21": [["Pilgrim's_Way_2","PILGRIM_TAB_02",21.54,15.2,{"es":"Aquí termina el Camino del Peregrino.\nEl corazón de Hallownest se encuentra ante ti.\nContinúa para ser testigo de su gloria.","en":"Here ends the Pilgrim's Way.\nHallownest's Heart lays open before you.\nProceed onward to share in its glory."}]],
    "Fungus2_30": [["Fungal_Core","FUNG_TAB_02",51.81,98.59,{"es":"Esos insectos me dan pena.\nSus mentes están bloqueadas. Ya no tienen más pensamientos.\nLas únicas palabras que intentan pronunciar son solo la sombra de una idea.","en":"Pity those bugs.\nMinds locked. Thoughts trapped in solitude.\nFaint shadow of an idea are the words that attempt its utterance."}]],
    "Fungus3_archive_02": [["Archives_Upper","ARCHIVE_01",96.95,162.79,{"es":"-SUSE-YEMA-ABA-AUSENCIA-CÁSCARA-EXTERIOR-PORTAL-CONTIENE\nRECEPTÁCULO-EN-LUZ-EN-HUEVO-EN-SELLO-SUSE-RETIRAR\nSELLO-O-EXTERIOR-ENTRE-SOÑADOR-DENTRO-FUERA\nCONTENER-LUZ-SUSE-SUEÑO-ARA-ABA-NODESARROLLO-CONTENER-","en":"-THIR-YOLK-ABA-ABSENCE-OUTER-SHELL-O-GATE-CONTAIN\nLIGHT-EM-VESSEL-EM-EGG-EM-SEAL-THIR-WITHDRAW\nEXTERIOR-O-SEAL-WITHIN-DREAMER-INTWIXT-ATWIXT\nCONTAIN-LIGHT-THIR-DREAM-CH-ABA-UNGROWTH-CONTAIN-"}],["Archives_Left","ARCHIVE_03",20.57,88.71,{"es":"-DE-AUSENCIA-SUSE-ABUNDANCIA-CÁSCARA-EXTERIOR-O-INTERIOR-\nCOLOCAR-IN-AUSENCIA-SUSE-VACÍO-SUSTANCIA-LÍQUIDA-O-\nTEJER-AUSENCIA-INTERIOR-O-CÁSCARA-EXTERIOR-SUSE-MATER\nMIRAR-CH-VACÍO-RECEPTÁCULO-AUSENCIA-TODO-EXTERIOR-CONTIENE-","en":"-OF-ABSENCE-THIR-ABUNDANCE-SHELL-OUTER-O-INNER-\nPLACE-IN-ABSENCE-THIR-VOID-LIQUID-SUBSTANCE-O-\nWEAVE-ABSENCE-INNER-O-SHELL-OUTER-THIR-MATER\nPEER-CH-VOID-VESSEL-ABSENCE-ALL-OUTER-CONTAIN-"}],["Archives_Right","ARCHIVE_02",97.84,78.77,{"es":"-LUZREY-EN-DESARROLLO-ENPROGENIE-FLUYE-TODOMENTE-ENVOLVE\nLUZVIEJA-EN-ESENCIA-EN-SUEÑO-EN-DESARROLLO\nO-FINMENTE-ABA-LUZREY-CH-LUZVIEJA-TEFAMILIA-O-CH\nFLUYEMENTE-ABA-SUEÑO-NOCONTENER-SUSE-DESARROLLO-FINVIDA-","en":"-KINGLIGHT-EM-GROWTH-INKIND-FLOW-ALLTHINK-ENFIELD\nOLDLIGHT-EM-ESSENCE-EM-DREAM-EM-UNGROWTH\nO-ENDTHINK-ABA-KINGLIGHT-CH-OLDLIGHT-THEMKIN-O-CH\nTHINKFLOW-ABA-DREAM-UNCONTAIN-THIR-UNGROWTH-ENDLIFE-"}]],
    "Room_Final_Boss_Atrium": [["World_Sense","SENSE_TAB_01",202.25,7.62,{"es":"Receptáculo. Aunque estés atrapado, conocerás el estado del mundo.\n\nHallownest será uno de nuevo.","en":"Vessel. Though bound, you shall know the state of the world.\n\nHallownest will be whole again."}]],
    "Ruins1_02": [["City_Entrance","RUIN_TAB_01",24.63,27.72,{"es":"Las grandes puertas han sido selladas. Nadie entrará. Nadie saldrá.","en":"The great gates have been sealed.\nNone shall enter.\nNone shall leave."}]],
    "Ruins1_23": [["Sanctum_Entrance","MAGE_COMP_03",41.13,67.92,{"es":"Informe Aba\nLa mente nos sigue limitando.\n¿Cómo podemos superar sus restricciones?\n¿Es posible conseguir una concentración perfecta?","en":"Record Aba \nThe mind still limits us so.\nHow to break past its constraints?\nTo attain a pure focus, is it even possible?"}]],
    "Ruins1_32": [["Sanctum_Past_Soul_Master","MAGE_COMP_01",36.04,99.2,{"es":"Informe Cenda\nEn recuerdo de los consumidos.\nHemos evolucionado gracias a su sacrificio.\nNinguna plaga mental nos superará ahora.","en":"Record Cenda\nSpare thought for those consumed.\nThrough their grace we are evolved.\nNo plague of mind shall overcome us now."}]],
    "Ruins2_Watcher_Room": [["Watcher's_Spire","LURIAN_JOURNAL",46.03,118.24,{"es":"El sueño eterno me llama. Estas palabras serán las últimas que pronuncie.\nAunque nunca volveré a posar mi mirada sobre esta ciudad, la protegeré durante toda la eternidad.\n\nPor el Rey, por los insectos, por Hallownest, ahora debo descansar.","en":"Sleep beckons eternal and these words become my last.\nThough my gaze shall no longer fall upon this city, I will act forever in its protection.\n\nFor King, for bug, for Hallownest, I head now to my rest."}]],
    "Ruins_Elevator": [["Pleasure_House","RUINS_MARISSA_POSTER",22.71,7.37,{"es":"Marissa, la Cantante\nSu voz alivia cualquier carga y trae la paz a las mentes perturbadas.","en":"Songstress Marissa\nA voice to ease all burdens and still all troubled minds."}]],
    "Tutorial_01": [["King's_Pass_Focus","TUT_TAB_01",111.46,34.66,{"es":"Seres superiores, estas palabras son solo para vosotros.\n \nVuestra enorme fuerza os distingue entre nosotros. Concentraos y realizaréis hazañas con las que otros solo pueden soñar.","en":"Higher beings, these words are for you alone. \n\nYour great strength marks you amongst us. Focus your soul and you shall achieve feats of which others can only dream."}],["King's_Pass_Fury","TUT_TAB_03",191.99,24.52,{"es":"Seres superiores, estas palabras son solo para vosotros.\n \nNo ocultéis vuestra auténtica forma en nuestras tierras. Dejad que admiremos vuestra majestuosidad, ya que solo de este reino podrían surgir seres como vosotros.","en":"Higher beings, these words are for you alone.\n\nWithin our lands do not hide your true form. Let all bask in your majesty, for only this kingdom could produce ones such as you."}],["King's_Pass_Exit","TUT_TAB_02",170.48,64.61,{"es":"Seres superiores, estas palabras son solo para vosotros.\n \nMás allá de este punto os espera la tierra del Rey y Creador. \nCruzad este umbral y obedeced sus leyes.\n\n\nSed testigos de la última y única civilización, el Reino Eterno.\n\nHallownest","en":"Higher beings, these words are for you alone.\n\nBeyond this point you enter the land of King and Creator.\nStep across this threshold and obey our laws.\n\n\nBear witness to the last and only civilisation, the eternal Kingdom.\n\nHallownest"}]],
    "Waterways_07": [["Dung_Defender","DUNG_DEF_SIGN",91.48,56.61,{"es":"La arboleda que hay más allá está reservada a aquellos que demuestren su valía en combate\n                El Defensor","en":"Only those who prove their honour in combat may enter the grove beyond.\n                                                             -The Defender"}]],
    "White_Palace_08": [["Palace_Workshop","WP_WORKSHOP_01",101.28,21.57,{"es":"VACÍO, tuyo es el poder opuesto.\nPero también tuyo es el potencial, el potencial de la eternidad, la fuerza que puede desafiar al tiempo.\nVACÍO, es necesario controlar tu poder.","en":"VOID, yours is the power opposed.\nBut yours is potential, eternity potential, force that could deny Time.\nVOID, harness shall be placed upon you."}]],
    "White_Palace_09": [["Palace_Throne","WP_THRONE_01",111.66,94.41,{"es":"Ningún pariente brillará. Solo habrá una luz que se enfrentará a las tinieblas.\nEl Wyrm se convertirá en el guía, y las mentes se expandirán, para aportar, para entregarse.\nLa promesa de la eternidad, y la carga en la progenie maldita.","en":"No blazing kin. Only one light shall shine against the dark.\nThe Wyrm becomes beacon, minds expanded, to yield, to devote.\nEternity in promise and charge in progeny cursed."}]],
    "White_Palace_18": [["Path_of_Pain_Entrance","PLAQUE_WARN",263.4,12.51,{"es":"Observar los secretos sellados, uno debe soportar el castigo más duro.","en":"To witness secrets sealed, one must endure the harshest punishment."}]],
  };
  HK.sceneObjects = { SIZES, ENEMIES, SECRETS, ROCKS, CHESTS, TOTEMS, TABLETS };
  if (typeof module !== 'undefined' && module.exports) module.exports = HK.sceneObjects;
